import{_ as n,o as e,c as i,a2 as l}from"./chunks/framework.DBU8LMUS.js";const k=JSON.parse('{"title":"Kelola Pengguna","description":"","frontmatter":{"title":"Kelola Pengguna","version":"1.0.0","last_updated":"2026-08-10T00:00:00.000Z","pdf_export":true},"headers":[],"relativePath":"latest/admin/pengguna.md","filePath":"latest/admin/pengguna.md","lastUpdated":1786334463000}'),o={name:"latest/admin/pengguna.md"};function t(u,a,m,d,r,s){return e(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="kelola-pengguna" tabindex="-1">Kelola Pengguna <a class="header-anchor" href="#kelola-pengguna" aria-label="Permalink to &quot;Kelola Pengguna&quot;">​</a></h1><h2 id="pendahuluan" tabindex="-1">Pendahuluan <a class="header-anchor" href="#pendahuluan" aria-label="Permalink to &quot;Pendahuluan&quot;">​</a></h2><p>Modul <strong>Kelola Pengguna</strong> memungkinkan <strong>super admin</strong> mengelola akun pengguna, termasuk <strong>mempromosikan pengguna menjadi admin</strong>, <strong>menyesuaikan kemampuan admin</strong>, dan <strong>menonaktifkan akun</strong> yang melanggar aturan.</p><div class="warning custom-block"><p class="custom-block-title">Hak Akses</p><p>Halaman ini (<code>/admin/users</code>) hanya dapat diakses oleh <strong>super admin</strong>. Admin biasa yang membuka halaman ini akan diarahkan ke dasbor admin.</p></div><h2 id="membuka-halaman-kelola-pengguna" tabindex="-1">Membuka Halaman Kelola Pengguna <a class="header-anchor" href="#membuka-halaman-kelola-pengguna" aria-label="Permalink to &quot;Membuka Halaman Kelola Pengguna&quot;">​</a></h2><ol><li>Masuk dengan akun <strong>super admin</strong>.</li><li>Buka menu <strong>Admin</strong>, lalu pilih <strong>Kelola Pengguna</strong>.</li><li>Daftar pengguna ditampilkan beserta informasi email, nama, peran, dan status akun.</li></ol><h2 id="mempromosikan-pengguna-menjadi-admin" tabindex="-1">Mempromosikan Pengguna Menjadi Admin <a class="header-anchor" href="#mempromosikan-pengguna-menjadi-admin" aria-label="Permalink to &quot;Mempromosikan Pengguna Menjadi Admin&quot;">​</a></h2><ol><li>Pada daftar pengguna, cari pengguna yang ingin dipromosikan.</li><li>Klik tombol <strong>Promosikan ke Admin</strong>.</li><li>Sistem akan menetapkan peran <code>admin</code> dengan <strong>kemampuan bawaan</strong> (semua kemampuan kecuali <code>manage_users</code>).</li><li>Pengguna tersebut langsung dapat mengakses panel admin sesuai kemampuannya.</li></ol><h3 id="menyesuaikan-kemampuan-admin" tabindex="-1">Menyesuaikan Kemampuan Admin <a class="header-anchor" href="#menyesuaikan-kemampuan-admin" aria-label="Permalink to &quot;Menyesuaikan Kemampuan Admin&quot;">​</a></h3><ol><li>Klik tombol <strong>Kelola Kemampuan</strong> pada baris pengguna berperan admin.</li><li>Centang atau hapus centang kemampuan yang diinginkan dari daftar: <ul><li><code>manage_alumni</code></li><li><code>moderate_jobs</code></li><li><code>moderate_announcements</code></li><li><code>moderate_polls</code></li><li><code>moderate_groups</code></li><li><code>moderate_gallery</code></li><li><code>moderate_reports</code></li><li><code>view_audit</code></li><li><code>import_export</code></li></ul></li><li>Klik <strong>Simpan</strong>.</li><li>Kemampuan admin langsung diperbarui.</li></ol><div class="tip custom-block"><p class="custom-block-title">Prinsip</p><p>Berikan hanya kemampuan yang dibutuhkan untuk tugas admin tersebut (prinsip hak akses minimum).</p></div><h2 id="menurunkan-admin-menjadi-pengguna-biasa" tabindex="-1">Menurunkan Admin Menjadi Pengguna Biasa <a class="header-anchor" href="#menurunkan-admin-menjadi-pengguna-biasa" aria-label="Permalink to &quot;Menurunkan Admin Menjadi Pengguna Biasa&quot;">​</a></h2><ol><li>Pada daftar pengguna, cari admin yang ingin diturunkan.</li><li>Klik tombol <strong>Turunkan ke Pengguna</strong>.</li><li>Konfirmasi tindakan.</li><li>Peran pengguna kembali menjadi <code>alumni</code> dan tidak dapat lagi mengakses panel admin.</li></ol><h2 id="menonaktifkan-akun-ban" tabindex="-1">Menonaktifkan Akun (Ban) <a class="header-anchor" href="#menonaktifkan-akun-ban" aria-label="Permalink to &quot;Menonaktifkan Akun (Ban)&quot;">​</a></h2><p>Akun dapat dinonaktifkan jika pengguna melanggar aturan komunitas.</p><ol><li>Pada daftar pengguna, klik tombol <strong>Nonaktifkan</strong> pada pengguna yang dituju.</li><li>Konfirmasi penonaktifan.</li><li>Pengguna tidak dapat masuk ke aplikasi hingga akun diaktifkan kembali.</li></ol><h3 id="mengaktifkan-kembali-akun" tabindex="-1">Mengaktifkan Kembali Akun <a class="header-anchor" href="#mengaktifkan-kembali-akun" aria-label="Permalink to &quot;Mengaktifkan Kembali Akun&quot;">​</a></h3><ol><li>Cari pengguna dengan status <strong>nonaktif</strong> pada daftar.</li><li>Klik tombol <strong>Aktifkan Kembali</strong>.</li><li>Akun pengguna kembali dapat digunakan.</li></ol><h2 id="melihat-log-aktivitas" tabindex="-1">Melihat Log Aktivitas <a class="header-anchor" href="#melihat-log-aktivitas" aria-label="Permalink to &quot;Melihat Log Aktivitas&quot;">​</a></h2><ol><li>Buka menu <strong>Admin</strong>, lalu pilih <strong>Log Aktivitas</strong> (<code>/admin/audit</code>).</li><li>Log menampilkan riwayat tindakan admin: perubahan peran, verifikasi alumni, penghapusan konten, dan lainnya.</li></ol><h2 id="tips-pengelolaan" tabindex="-1">Tips Pengelolaan <a class="header-anchor" href="#tips-pengelolaan" aria-label="Permalink to &quot;Tips Pengelolaan&quot;">​</a></h2><ul><li>Promosikan admin hanya kepada pengguna yang dipercaya dan dikenal.</li><li>Tinjau kembali kemampuan admin secara berkala.</li><li>Dokumentasikan keputusan penonaktifan akun untuk keperluan audit.</li></ul><p>Lanjutkan ke <a href="/webapps/latest/admin/alumni">Kelola Alumni</a> untuk mengelola data dan verifikasi alumni.</p>',23)])])}const p=n(o,[["render",t]]);export{k as __pageData,p as default};
